              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>
      <div className="flex ml-auto items-center gap-2">
        <Button
          variant="ghost"
          className="underline"
          onClick={() => setSelectedCode(null)}
          disabled={!selectedCode}
        >
          {t("clear")}
        </Button>
        <Button
          onClick={() => {
            if (!selectedCode) return;
            onCreateReport(selectedCode);
            setSelectedCode(null);
