                conclusion={conclusion}
                onConclusionChange={setEditedConclusion}
                disableEdit={disableEdit || isUpdatingReport}
                canApprove={canApprove}
                onApprove={handleApprove}
              />
            )}
          </CardContent>
        </CollapsibleContent>
      </Collapsible>
    </Card>
  );
}
