import { expect, test, type Page } from "@playwright/test";
import {
  createActivityDefinition,
  DIAGNOSTIC_REPORT_CODES,
} from "tests/facility/settings/activityDefinition/activityDefinition";
import {
  clickTabOrMenuItem,
  closeAnyOpenPopovers,
  expectToast,
  selectFromRequirements,
  selectFromValueSet,
} from "tests/helper/ui";
import { getEncounterId } from "tests/support/encounterId";
import { getFacilityId } from "tests/support/facilityId";
import { getPatientId } from "tests/support/patientId";

import { createServiceRequest } from "./serviceRequest";

test.use({ storageState: "tests/.auth/user.json" });

const reportTypes = DIAGNOSTIC_REPORT_CODES.slice(0, 2);

function getReportCards(page: Page, reportType: string) {
  return page.locator('[data-slot="collapsible"]').filter({
    has: page.locator('[data-slot="collapsible-trigger"]').filter({
      hasText: reportType,
    }),
  });
}

async function createReport(page: Page, reportType: string) {
  await page
    .getByRole("combobox")
    .filter({ hasText: "Select Diagnostic Report Type" })
    .click();
  await page.getByRole("option", { name: reportType }).click();
  await page
    .getByRole("button", { name: "Create Report", exact: true })
    .click();
  await expectToast(page, "Diagnostic report created successfully");
  await expect(
    getReportCards(page, reportType).first().getByPlaceholder("Result value"),
  ).toBeVisible();
}

test.describe("Multiple diagnostic reports", () => {
  let facilityId: string;
  let activityTitle: string;

  test.beforeAll(async ({ browser }) => {
    facilityId = getFacilityId();
    const page = await browser.newPage({
      storageState: "tests/.auth/user.json",
    });

    try {
      const activity = await createActivityDefinition(page, facilityId, false, {
        status: "Active",
        classification: "Laboratory",
      });
      activityTitle = activity.title;

      await page.goto(
        `/facility/${facilityId}/settings/activity_definitions/f-${facilityId}-${activity.slug}/edit`,
      );
      await selectFromRequirements(
        page,
        page
          .getByRole("combobox")
          .filter({ hasText: /select observation requirements/i }),
        { search: "Fasting Blood Glucose" },
      );
      await closeAnyOpenPopovers(page);

      for (const reportType of reportTypes) {
        await selectFromValueSet(
          page,
          page.getByRole("combobox").filter({ hasText: /search.*diagnostic/i }),
          { search: reportType },
        );
      }

      await page.getByRole("button", { name: "Save", exact: true }).click();
      await expectToast(page, "Activity definition updated successfully");
    } finally {
      await page.close();
    }
  });

  test("keeps each report's unsaved results when creating and saving another report", async ({
    page,
  }) => {
    const patientId = getPatientId();
    const encounterId = getEncounterId();
    const [firstReportType, secondReportType] = reportTypes;

    await test.step("Open a service request with two report types", async () => {
      await createServiceRequest(
        page,
        facilityId,
        patientId,
        encounterId,
        false,
        { activityDefinition: activityTitle },
      );
      await clickTabOrMenuItem(page, /service requests/i);
      await page
        .getByRole("row")
        .filter({ hasText: activityTitle })
        .getByRole("button", { name: "See Details" })
        .click();
    });

    const firstEntry = getReportCards(page, firstReportType).first();
    const secondEntry = getReportCards(page, secondReportType).first();
    const firstReview = getReportCards(page, firstReportType).last();
    const secondReview = getReportCards(page, secondReportType).last();
    const reportCards = getReportCards(page, firstReportType).or(
      getReportCards(page, secondReportType),
    );

    await test.step("Keep the first report's draft when creating a second report", async () => {
      await createReport(page, firstReportType);
      await firstEntry.getByPlaceholder("Result value").fill("101");
      await firstEntry.getByPlaceholder("Enter Conclusion").fill("First draft");

      await page
        .getByRole("button", { name: "Another Diagnostic Report" })
        .click();
      await createReport(page, secondReportType);

      await expect(reportCards.nth(0)).toContainText(firstReportType);
      await expect(reportCards.nth(1)).toContainText(secondReportType);
      await expect(firstEntry.getByPlaceholder("Result value")).toHaveValue(
        "101",
      );
      await expect(firstEntry.getByPlaceholder("Enter Conclusion")).toHaveValue(
        "First draft",
      );
      await secondEntry.getByPlaceholder("Result value").fill("202");
      await secondEntry
        .getByPlaceholder("Enter Conclusion")
        .fill("Second draft");
    });

    await test.step("Save the first report without resetting the second draft", async () => {
      await firstEntry.getByRole("button", { name: "Save Results" }).click();
      await expectToast(page, "Test results saved successfully");
      await expect(reportCards.nth(0)).toContainText(firstReportType);
      await expect(reportCards.nth(1)).toContainText(secondReportType);
      await expect(
        firstEntry.getByPlaceholder("Result value"),
      ).not.toBeVisible();
      await expect(
        firstReview.getByRole("button", { name: "Approve Results" }),
      ).toBeVisible();
      await expect(
        firstReview.getByPlaceholder("Enter Conclusion"),
      ).toHaveValue("First draft");
      await expect(secondEntry.getByPlaceholder("Result value")).toHaveValue(
        "202",
      );
      await expect(
        secondEntry.getByPlaceholder("Enter Conclusion"),
      ).toHaveValue("Second draft");
    });

    await test.step("Keep an edited saved report when saving the other report", async () => {
      await firstEntry.locator('[data-slot="collapsible-trigger"]').click();
      await firstEntry.getByPlaceholder("Result value").fill("303");
      await firstEntry
        .getByPlaceholder("Enter Conclusion")
        .fill("Revised first draft");
      await secondEntry.getByRole("button", { name: "Save Results" }).click();
      await expectToast(page, "Test results saved successfully");

      await expect(reportCards.nth(0)).toContainText(firstReportType);
      await expect(reportCards.nth(1)).toContainText(secondReportType);
      await expect(firstEntry.getByPlaceholder("Result value")).toHaveValue(
        "303",
      );
      await expect(firstEntry.getByPlaceholder("Enter Conclusion")).toHaveValue(
        "Revised first draft",
      );
      await expect(
        secondReview.getByPlaceholder("Enter Conclusion"),
      ).toHaveValue("Second draft");
    });

    await test.step("Reopen the correct review after saving that report again", async () => {
      await firstReview.locator('[data-slot="collapsible-trigger"]').click();
      await expect(
        firstReview.getByPlaceholder("Enter Conclusion"),
      ).not.toBeVisible();
      await firstEntry.getByRole("button", { name: "Save Results" }).click();
      await expectToast(page, "Test results saved successfully");

      await expect(
        firstReview.getByRole("button", { name: "Approve Results" }),
      ).toBeVisible();
      await expect(
        firstReview.getByPlaceholder("Enter Conclusion"),
      ).toHaveValue("Revised first draft");

      await page.reload();
      await expect(firstEntry.getByPlaceholder("Result value")).toHaveValue(
        "303",
      );
      await expect(firstEntry.getByPlaceholder("Enter Conclusion")).toHaveValue(
        "Revised first draft",
      );
      await expect(secondEntry.getByPlaceholder("Result value")).toHaveValue(
        "202",
      );
      await expect(
        secondEntry.getByPlaceholder("Enter Conclusion"),
      ).toHaveValue("Second draft");
    });
  });
});
import PrintPreview from "@/CAREUI/misc/PrintPreview";
import PrintFooter from "@/components/Common/PrintFooter";
import { DiagnosticReportResultsTable } from "@/pages/Facility/services/diagnosticReports/components/DiagnosticReportResultsTable";
import { DiagnosticReportRead } from "@/types/emr/diagnosticReport/diagnosticReport";
import { ObservationStatus } from "@/types/emr/observation/observation";
import { PrintTemplateType } from "@/types/facility/printTemplate";
import { FileReadMinimal } from "@/types/files/file";
import fileApi from "@/types/files/fileApi";
import { PatientIdentifierUse } from "@/types/patient/patientIdentifierConfig/patientIdentifierConfig";
import query from "@/Utils/request/query";
import { formatName, formatPatientAge } from "@/Utils/utils";
import { useQueries } from "@tanstack/react-query";
import { format } from "date-fns";
import { ReactNode, useCallback, useRef, useState } from "react";
import { useTranslation } from "react-i18next";

import "@/lib/pdfWorker";
import { useCurrentFacilitySilently } from "@/pages/Facility/utils/useCurrentFacility";
import { Document, Page } from "react-pdf";

// Fixed printable page width (px). The rendered PDF/image sizes the paper, not
// the screen, so this must not depend on the (non-reactive) viewport width.
const PRINT_PAGE_WIDTH = 600;

interface AttachmentRendererProps {
  fileUrl: string;
  onReady: (fileUrl: string) => void;
  onError: (fileUrl: string) => void;
}

// TODO: Replace with PDFViewer or extract this to a component
function PDFRenderer({ fileUrl, onReady, onError }: AttachmentRendererProps) {
  const [numPages, setNumPages] = useState<number>(0);
  const renderedPages = useRef(new Set<number>());
  const { t } = useTranslation();

  return (
    <div className="break-before-page">
      <Document
        file={fileUrl}
        onLoadSuccess={({ numPages }) => setNumPages(numPages)}
        onLoadError={() => onError(fileUrl)}
        onSourceError={() => onError(fileUrl)}
        error={<div className="text-red-500">{t("error_loading_pdf")}</div>}
        loading={<div className="text-gray-500">{t("loading")}</div>}
      >
        <div className="flex flex-col justify-center w-full">
          {Array.from(new Array(numPages), (_, index) => (
            <Page
              key={`page_${index + 1}`}
              pageNumber={index + 1}
              width={PRINT_PAGE_WIDTH}
              scale={1.2}
              renderTextLayer={false}
              renderAnnotationLayer={false}
              onRenderSuccess={() => {
                renderedPages.current.add(index);
                if (renderedPages.current.size === numPages) {
                  onReady(fileUrl);
                }
              }}
              onLoadError={() => onError(fileUrl)}
              onRenderError={() => onError(fileUrl)}
            />
          ))}
        </div>
      </Document>
    </div>
  );
}

function ImageRenderer({
  fileUrl,
  fileName,
  onReady,
  onError,
}: AttachmentRendererProps & {
  fileName?: string;
}) {
  const { t } = useTranslation();
  const [isLoading, setIsLoading] = useState(true);
  const [hasError, setHasError] = useState(false);

  return (
    <div className="break-before-page flex flex-col justify-center w-full">
      {isLoading && (
        <div className="text-gray-500 text-center py-4">{t("loading")}</div>
      )}
      {hasError && (
        <div className="text-red-500 text-center py-4">
          {t("error_loading_image")}
        </div>
      )}
      <img
        src={fileUrl}
        alt={fileName || t("diagnostic_report_image")}
        className={`max-w-[600px] h-auto mx-auto ${isLoading || hasError ? "hidden" : ""}`}
        onLoad={() => {
          setIsLoading(false);
          onReady(fileUrl);
        }}
        onError={() => {
          setIsLoading(false);
          setHasError(true);
          onError(fileUrl);
        }}
      />
    </div>
  );
}

