      facilityId,
      patientId,
      encounterId,
      false,
      { activityDefinition: "Urinalysis" },
    );

    await clickTabOrMenuItem(page, /service requests/i);
    await expect(page).toHaveURL(/\/service_requests$/);
    await page
      .locator('[data-slot="table-body"] [data-slot="table-row"]')
