}

export interface ObservationBatchUpsertRequest {
  observations: ObservationUpsertRequest[];
}

export interface ObservationBatchUpsertResponse {
  message: string;
}

export type ObservationPlotConfig = {
  id: string;
  name: string;
  groups: {
    title: string;
    codes: Code[];
  }[];
