from datetime import datetime
from enum import Enum

from pydantic import UUID4, BaseModel, Field

from care.emr.models.observation import Observation
from care.emr.resources.base import EMRResource, model_from_cache
from care.emr.resources.common import Coding
from care.emr.resources.common.codable_concept import CodeableConcept
from care.emr.resources.observation.valueset import (
    CARE_BODY_SITE_VALUESET,
    CARE_OBSERVATION_COLLECTION_METHOD,
)
from care.emr.resources.observation_definition.spec import BaseObservationDefinitionSpec
from care.emr.resources.questionnaire.spec import QuestionType, SubjectType
from care.emr.resources.questionnaire_response.spec import (
    QuestionnaireSubmitResultValue,
)
from care.emr.resources.user.spec import UserSpec
from care.emr.utils.valueset_coding_type import ValueSetBoundCoding


class ObservationStatus(str, Enum):
    final = "final"
    amended = "amended"
    entered_in_error = "entered_in_error"


class PerformerType(str, Enum):
    related_person = "related_person"
    user = "user"


class Performer(BaseModel):
    type: PerformerType
    id: str


class ReferenceRange(BaseModel):
    min: float | None = None
    max: float | None = None
    unit: str | None = None
    interpretation: str
    value: str | None = None


class Component(BaseModel):
    value: QuestionnaireSubmitResultValue
    interpretation: str | dict = {}
    reference_range: list[ReferenceRange] = []
    code: Coding | None = None
    note: str = ""


class BaseObservationSpec(EMRResource):
    __model__ = Observation

    id: UUID4 | None = Field(None, description="Unique ID in the system")

    status: ObservationStatus = Field(
        description="Status of the observation (final or amended)"
    )

    category: Coding | None = None

    main_code: Coding | None = None

    alternate_coding: CodeableConcept | None = None

    subject_type: SubjectType = SubjectType.encounter.value

    encounter: UUID4 | None = None

    effective_datetime: datetime

    performer: Performer | None = None

    value_type: QuestionType

    value: QuestionnaireSubmitResultValue

    note: str | None = None

    body_site: ValueSetBoundCoding[CARE_BODY_SITE_VALUESET.slug] | None = None

    method: ValueSetBoundCoding[CARE_OBSERVATION_COLLECTION_METHOD.slug] | None = None

    reference_range: list[ReferenceRange] = []

    interpretation: dict = {}

    parent: UUID4 | None = None

    questionnaire_response: UUID4 | None = None

    component: list[Component] = []


class ObservationUpdateSpec(BaseObservationSpec):
    effective_datetime: datetime | None = None
    value: QuestionnaireSubmitResultValue | None = None


class ObservationSpec(BaseObservationSpec):
    data_entered_by_id: int
    created_by_id: int
    updated_by_id: int

    def perform_extra_deserialization(self, is_update, obj):
        obj.external_id = self.id
        obj.data_entered_by_id = self.data_entered_by_id
        obj.created_by_id = self.created_by_id
        obj.updated_by_id = self.updated_by_id

        self.meta.pop("data_entered_by_id", None)
        if not is_update:
            obj.id = None


class ObservationReadSpec(BaseObservationSpec):
    created_by: UserSpec = {}
    updated_by: UserSpec = {}
    data_entered_by: UserSpec | None = None

    @classmethod
    def perform_extra_serialization(cls, mapping, obj):
        mapping["id"] = obj.external_id
        # Avoiding extra queries
        mapping["encounter"] = None
        mapping["patient"] = None
        mapping["questionnaire_response"] = None

        cls.serialize_audit_users(mapping, obj)
        if obj.data_entered_by:
            mapping["data_entered_by"] = model_from_cache(
                UserSpec, id=obj.data_entered_by_id
            )


class ObservationRetrieveSpec(ObservationReadSpec):
    observation_definition: dict | None = None

    @classmethod
    def perform_extra_serialization(cls, mapping, obj):
        super().perform_extra_serialization(mapping, obj)
        if obj.observation_definition:
            mapping["observation_definition"] = BaseObservationDefinitionSpec.serialize(
                obj.observation_definition
            )
from django_filters import rest_framework as filters
from rest_framework.decorators import action
from rest_framework.exceptions import PermissionDenied, ValidationError
from rest_framework.filters import OrderingFilter
from rest_framework.response import Response

from care.emr.api.viewsets.base import (
    EMRBaseViewSet,
    EMRCreateMixin,
    EMRListMixin,
    EMRRetrieveMixin,
    EMRUpdateMixin,
    EMRUpsertMixin,
)
from care.emr.models.observation_definition import ObservationDefinition
from care.emr.resources.observation_definition.spec import (
    ObservationDefinitionCreateSpec,
    ObservationDefinitionReadSpec,
    ObservationDefinitionUpdateSpec,
)
from care.facility.models import Facility
from care.security.authorization import AuthorizationController
from care.utils.registries.evaluation_metric import EvaluatorMetricsRegistry
from care.utils.shortcuts import get_object_or_404


class ObservationDefinitionFilters(filters.FilterSet):
    facility = filters.UUIDFilter(field_name="facility__external_id")
    category = filters.CharFilter(lookup_expr="iexact")
    status = filters.CharFilter(lookup_expr="iexact")
    title = filters.CharFilter(lookup_expr="icontains")


class ObservationDefinitionViewSet(
    EMRCreateMixin,
    EMRRetrieveMixin,
    EMRUpdateMixin,
    EMRListMixin,
    EMRBaseViewSet,
    EMRUpsertMixin,
):
    lookup_field = "slug"
    database_model = ObservationDefinition
    pydantic_model = ObservationDefinitionCreateSpec
    pydantic_update_model = ObservationDefinitionUpdateSpec
    pydantic_read_model = ObservationDefinitionReadSpec
    filterset_class = ObservationDefinitionFilters
    filter_backends = [filters.DjangoFilterBackend, OrderingFilter]
    ordering_fields = ["created_date", "modified_date"]

    def recalculate_slug(self, instance):
        if instance.facility:
            instance.slug = ObservationDefinition.calculate_slug_from_facility(
                instance.facility.external_id, instance.slug
            )
        else:
            instance.slug = ObservationDefinition.calculate_slug_from_instance(
                instance.slug
            )

    def perform_create(self, instance):
        self.recalculate_slug(instance)
        super().perform_create(instance)

    def perform_update(self, instance):
        self.recalculate_slug(instance)
        return super().perform_update(instance)

    def validate_data(self, instance, model_obj=None):
        queryset = ObservationDefinition.objects.all()
        facility = None
        if model_obj:
            queryset = queryset.exclude(id=model_obj.id)
            if model_obj.facility:
                facility = str(model_obj.facility.external_id)
        else:
            facility = instance.facility

        if facility:
            slug = ObservationDefinition.calculate_slug_from_facility(
                facility, instance.slug_value
            )
        else:
            slug = ObservationDefinition.calculate_slug_from_instance(
                instance.slug_value
            )

        queryset = queryset.filter(slug__iexact=slug)
        if queryset.exists():
            raise ValidationError("Slug already exists.")

        return super().validate_data(instance, model_obj)

    def authorize_create(self, instance):
        """
        Only superusers can create observation definitions that are not facility-specific.
        The user must have permission to create the observation definition in the facility.
        """
        if not instance.facility and not self.request.user.is_superuser:
            raise PermissionDenied("Access Denied to Observation Definition")
        if instance.facility and not AuthorizationController.call(
            "can_write_facility_observation_definition",
            self.request.user,
            get_object_or_404(Facility, external_id=instance.facility),
        ):
            raise PermissionDenied("Access Denied to Observation Definition")

    def authorize_update(self, request_obj, model_instance):
        """
        Only superusers can update observation definitions that are not facility-specific.
        The user must have permission to update the observation definition in the facility.
        """
        if not model_instance.facility and not self.request.user.is_superuser:
            raise PermissionDenied("Access Denied to Observation Definition")

        if model_instance.facility and not AuthorizationController.call(
            "can_write_facility_observation_definition",
            self.request.user,
            model_instance.facility,
        ):
            raise PermissionDenied("Access Denied to Observation Definition")

    def authorize_retrieve(self, model_instance):
        if not model_instance.facility:
            # All users can view non-facility specific observation definitions
            return
        if not AuthorizationController.call(
            "can_list_facility_observation_definition",
            self.request.user,
            model_instance.facility,
        ):
            raise PermissionDenied("Access Denied to Observation Definition")

    def get_queryset(self):
        """
        If no facility filters are applied, all objects must be returned without a facility filter.
        If facility filter is applied, check for read permission and return all inside facility.
        """
        base_queryset = super().get_queryset()
        if self.action in ["list"]:
            if "facility" in self.request.GET:
                facility_id = self.request.GET["facility"]
                facility_obj = get_object_or_404(Facility, external_id=facility_id)
                if not AuthorizationController.call(
                    "can_list_facility_observation_definition",
                    self.request.user,
                    facility_obj,
                ):
                    raise PermissionDenied("Access Denied to Observation Definition")
                return base_queryset.filter(facility=facility_obj)
            base_queryset = base_queryset.filter(facility__isnull=True)
        return base_queryset

    @action(detail=False, methods=["GET"])
    def metrics(self, request, *args, **kwargs):
        all_metrics = EvaluatorMetricsRegistry.get_all_metrics()
        response = []
        for metric in all_metrics:
            response.append(
                {
                    "name": metric.name,
                    "verbose_name": metric.verbose_name,
                    "context": metric.context,
                    "allowed_operations": metric.allowed_operations,
                }
            )
        return Response(response)

