                                    </div>
                                  </div>
                                )}

                                {/* Render component inputs for multi-component observations */}
                                {hasComponents &&
                                  renderComponentInputs(
                                    definition,
                                    observationData,
                                    index,
                                  )}
                              </div>
                            );
                          })}

                          {/* Add button for multiple observations */}
                          <Button
                            type="button"
                            variant="outline"
                            size="sm"
                            onClick={() => {
                              setObservations((prev) => {
                                const currentList = prev[definition.id] || [];
                                return {
                                  ...prev,
                                  [definition.id]: [
                                    ...currentList,
                                    {
                                      id: "",
                                      value: "",
                                      unit:
                                        definition.permitted_unit?.code || "",
                                      status: ObservationStatus.AMENDED,
                                      components: {},
                                    },
                                  ],
                                };
                              });
                            }}
                            disabled={isReadOnly}
                          >
                            <PlusCircle className="size-4 mr-2" />
                            {t("add_another_result")}
                          </Button>
                        </div>
                      </CardContent>
                    </Card>
                  );
                })}

              <div className="space-y-4">
                {report.status !== DiagnosticReportStatus.final && (
                  <Card className="mb-4 shadow-none rounded-lg border-gray-200 bg-gray-50">
                    <CardContent className="p-4 space-y-2">
                      <Label
                        htmlFor={`conclusion-${report.id}`}
                        className="text-base font-semibold text-gray-950"
                      >
                        {t("conclusion")}
                      </Label>
                      <textarea
                        id={`conclusion-${report.id}`}
                        className="w-full field-sizing-content focus:outline-none focus:ring-1 focus:ring-primary-500 focus:border-primary-500 rounded-lg border border-gray-300 p-2"
                        placeholder={t("enter_conclusion")}
                        value={conclusion}
                        onChange={(e) => setConclusion(e.target.value)}
                        rows={3}
                        disabled={isReadOnly}
                      />
                    </CardContent>
                  </Card>
                )}

                <div className="space-y-4">
                  {fullReport?.status ===
                    DiagnosticReportStatus.preliminary && (
                    <div className="flex justify-end space-x-4">
                      <Button
                        variant="primary"
                        onClick={handleSubmit}
                        disabled={isReadOnly}
                      >
                        <Save className="size-4 mr-2" />
                        {t("save_results")}
                      </Button>
                    </div>
                  )}
                  {files?.results && files.results.length > 0 && (
                    <div className="mt-3">
                      <div className="text-lg font-medium">
                        {t("uploaded_files")}
                      </div>
                      <FileListTable
                        files={files.results}
                        type="diagnostic_report"
                        associatingId={report.id}
                        canEdit={!isReadOnly}
                        showHeader={false}
                      />
                    </div>
                  )}

                  {fullReport?.status ===
                    DiagnosticReportStatus.preliminary && (
                    <div className="space-y-5">
                      <DottedDivider className=" text-gray-500" />
                      <div className="rounded-lg border border-gray-200 bg-gray-50 px-6 py-5 shadow-sm mt-2">
                        <div className="flex flex-col items-center text-center">
                          <h3 className="text-base font-semibold text-gray-950">
                            {t("attach_result_files")}
                          </h3>
                          <p className="mt-1.5 text-sm text-gray-600">
                            {t("add_supporting_photos_or_documents", {
                              formats:
                                BACKEND_ALLOWED_EXTENSIONS.slice(0, 5)
                                  .join(", ")
                                  .toUpperCase() + `, ${t("etc")}`,
                            })}
                          </p>
                          <div className="mt-4 flex flex-col sm:flex-row gap-3 w-full sm:items-center sm:justify-center">
                            <Button
                              variant="outline"
                              className=" border-gray-300 bg-white font-semibold text-gray-950 shadow-sm hover:bg-white"
                              disabled={isReadOnly}
                              onClick={() => fileUpload.handleCameraCapture()}
                            >
                              <Camera className="size-4" />
                              {t("take_photo")}
                            </Button>
                            <Button
                              asChild
                              variant="outline"
                              className={cn(
                                "border-gray-300 bg-white font-semibold text-gray-950 shadow-sm hover:bg-white",
                                isReadOnly
                                  ? "pointer-events-none opacity-50"
                                  : "cursor-pointer",
                              )}
                            >
                              <Label htmlFor={isReadOnly ? undefined : inputId}>
                                <Upload className="size-4" />
                                {t("upload_files")}
                              </Label>
                            </Button>
                            <fileUpload.Input
                              className="hidden"
                              disabled={isReadOnly}
                            />
                          </div>

                          {fileUpload.files.length > 0 && (
                            <div className="mt-5 w-full max-w-md space-y-2">
                              <div
                                className="truncate text-sm text-gray-600"
                                title={fileUpload.files
                                  .map((file) => file.name)
                                  .join(", ")}
                              >
                                {fileUpload.files
                                  .map((file) => file.name)
                                  .join(", ")}
                              </div>
                              <Button
                                type="button"
                                variant="outline"
                                className="w-full border-gray-300 bg-white"
                                disabled={isReadOnly}
                                onClick={() => fileUpload.clearFiles()}
                              >
                                {t("clear")}
                              </Button>
                            </div>
                          )}
                        </div>
                      </div>
                    </div>
                  )}
                </div>
              </div>
            </div>
          </CardContent>
        </CollapsibleContent>
      </Collapsible>

      {fileUpload.Dialogues}
      <FileUploadDialog
        open={openUploadDialog}
        onOpenChange={(open) => {
          if (!open) fileUpload.clearFiles();
        }}
        fileUpload={fileUpload}
        associatingId={report?.id || ""}
        type="diagnostic_report"
        instanceId={report?.id || ""}
      />
    </Card>
  );
}

function ReportTypePicker({
  availableReportCodes,
  hasCollectedSpecimens,
  disableEdit,

item.aggregated_output:
  onReportSaved,
}: {
  report: DiagnosticReportRead;
  patientId: string;
  serviceRequestId: string;
  observationDefinitions: ObservationDefinitionRead[];
  disableEdit: boolean;
  facilityId: string;
  isMultipleDiagnosticReport: boolean;
  onReportSaved: (report: SavedReportSignal) => void;
}) {
  const { t } = useTranslation();
  const queryClient = useQueryClient();
  const [observationDraft, setObservationDraft] =
    useState<ObservationsByDefinition | null>(null);
  const [isExpanded, setIsExpanded] = useState(true);
  const [conclusionDraft, setConclusion] = useState<string | undefined>();

  const { data: fullReport } = useQuery({
    queryKey: ["diagnosticReport", report.id],
    queryFn: query(diagnosticReportApi.retrieveDiagnosticReport, {
      pathParams: {
        patient_external_id: patientId,
        external_id: report.id,
      },
    }),
    enabled: !!report.id && isExpanded,
  });

  // Query to fetch files for the diagnostic report
  const { data: files } = useQuery({
    queryKey: ["files", "diagnostic_report", report.id],
    queryFn: query.paginated(fileApi.list, {
      queryParams: {
        file_type: "diagnostic_report",
        associating_id: report.id,
      },
    }),
    enabled: !!report.id && isExpanded,
  });

  // Save observations and update the diagnostic report in a single batch request
  const { mutate: saveReport, isPending: isSubmitting } = useBatchRequest({
    onSuccess: async ({ results }) => {
      if (results.some((r) => r.reference_id === "upsert-observations")) {
        toast.success(t("test_results_saved_successfully"));
      } else {
        toast.success(t("diagnostic_report_saved_successfully"));
      }
      await Promise.all([
        queryClient.invalidateQueries({
          queryKey: ["serviceRequest", facilityId, serviceRequestId],
        }),
        queryClient.invalidateQueries({
          queryKey: ["diagnosticReport", report.id],
        }),
      ]);
      setObservationDraft(null);
      setConclusion(undefined);
      setIsExpanded(false);
      onReportSaved({ id: report.id, savedAt: Date.now() });
    },
  });

  // Initialize file upload hook
  const inputId = `file_upload_diagnostic_report_${report.id}`;
  const fileUpload = useFileUpload({
    type: FileType.DIAGNOSTIC_REPORT,
    inputId,
    multiple: true,
    allowedExtensions: BACKEND_ALLOWED_EXTENSIONS,
    allowNameFallback: false,
    onUpload: () => {
      queryClient.invalidateQueries({
        queryKey: ["diagnosticReport", report.id],
      });
    },
    compress: false,
  });

  const openUploadDialog =
    !disableEdit && fileUpload.files.length > 0 && !fileUpload.previewing;
  const observations = observationDraft ?? getReportObservations(fullReport);
  const conclusion = conclusionDraft ?? fullReport?.conclusion ?? "";
  const isReadOnly =
    disableEdit ||
    !fullReport ||
    isSubmitting ||
    fullReport.status === DiagnosticReportStatus.final;

  function setObservations(
    update: (previous: ObservationsByDefinition) => ObservationsByDefinition,
  ) {
    setObservationDraft((previous) =>
      update(previous ?? getReportObservations(fullReport)),
    );
  }

  function handleValueChange(
    definitionId: string,
    index: number,
    value: string,
    unit?: string,
  ) {
    setObservations((prev) => {
      const observationsList = [...(prev[definitionId] || [])];
      if (!observationsList[index]) {
        observationsList[index] = {
          id: "",
          value: "",
          unit: unit || "",
          status: ObservationStatus.AMENDED,
          components: {},
        };
      }
      observationsList[index] = {
        ...observationsList[index],
        value,
      };
      return {
        ...prev,
        [definitionId]: observationsList,
      };
    });
  }

  function handleUnitChange(definitionId: string, index: number, unit: string) {
    setObservations((prev) => {
      const observationsList = [...(prev[definitionId] || [])];
      if (!observationsList[index]) {
        observationsList[index] = {
          id: "",
          value: "",
          unit: "",
          status: ObservationStatus.AMENDED,
          components: {},
        };
      }
      observationsList[index] = {
        ...observationsList[index],
        unit,
      };
      return {
        ...prev,
        [definitionId]: observationsList,
      };
    });
  }

  function handleComponentValueChange(
    definitionId: string,
    index: number,
    componentCode: string,
    value: string,
    unit: string,
  ) {
    setObservations((prev) => {
      const observationsList = [...(prev[definitionId] || [])];
      if (!observationsList[index]) {
        observationsList[index] = {
          id: "",
          value: "",
          unit: "",
          status: ObservationStatus.AMENDED,
          components: {},
        };
      }
      const observation = observationsList[index];
      const components = { ...observation.components };

      components[componentCode] = {
        ...components[componentCode],
        value,
        unit,
      };

      observationsList[index] = {
        ...observation,
        components,
      };

      return {
        ...prev,
        [definitionId]: observationsList,
      };
    });
  }

  function handleComponentUnitChange(
    definitionId: string,
    index: number,
    componentCode: string,
    unit: string,
  ) {
    setObservations((prev) => {
      const observationsList = [...(prev[definitionId] || [])];
      if (!observationsList[index]) {
        observationsList[index] = {
          id: "",
          value: "",
          unit: "",
          status: ObservationStatus.AMENDED,
          components: {},
        };
      }
      const observation = observationsList[index];
      const components = { ...observation.components };

      components[componentCode] = {
        ...(components[componentCode] || { value: "", interpretation: "" }),
        unit,
      };

      observationsList[index] = {
        ...observation,
        components,
      };

      return {
        ...prev,
        [definitionId]: observationsList,
      };
    });
  }

  function handleSubmit() {
    if (isReadOnly) return;
    try {
      // Check if all observations have values
      const hasObservationValue = Object.values(observations).some((obsList) =>
        obsList.some((obs) => {
          // Skip observations marked as deleted
          if (obs.status === ObservationStatus.ENTERED_IN_ERROR) {
            return false;
          }
          const hasMainValue = obs.value.trim() !== "";
          const hasComponentValue = Object.values(obs.components).some(
            (comp) => comp.value.trim() !== "",
          );
          return hasMainValue || hasComponentValue;
        }),
      );

      // Check if any observations are marked for deletion
      const hasDeletions =
        !hasObservationValue &&
        Object.values(observations).some((obsList) =>
          obsList.some(
            (obs) => obs.status === ObservationStatus.ENTERED_IN_ERROR,
          ),
        );

      // If there's a conclusion, we must have results first
      if (
        conclusion.trim() &&
        !hasObservationValue &&
        observationDefinitions.length > 0
      ) {
        toast.error(t("cannot_add_conclusion_without_results"));
        return;
      }

      // Results are mandatory if observation definitions exist, unless an observation is being deleted
      if (
        !hasObservationValue &&
        !hasDeletions &&
        observationDefinitions.length > 0
      ) {
        toast.error(t("please_fill_all_results"));
        return;
      }

      const formattedObservations: ObservationUpsertRequest[] = Object.entries(
        observations,
      )
        .flatMap(([definitionId, obsList]) =>
          obsList.map((obsData): ObservationUpsertRequest | null => {
            const observationDefinition = observationDefinitions.find(
              (def) => def.id === definitionId,
            );

            // If it's a component-based observation (like blood pressure), we should check if components have values
            const hasComponents =
              observationDefinition?.component &&
              observationDefinition.component.length > 0;
            const hasComponentValues =
              hasComponents &&
              Object.values(obsData.components).some(
                (comp) => comp.value.trim() !== "",
              );

            // For observations marked for deletion, always include them if they have an ID
            const isMarkedForDeletion =
              obsData.status === ObservationStatus.ENTERED_IN_ERROR &&
              obsData.id;

            // For regular observations, skip if no value is entered
            // For component-based observations, check component values
            // But always include observations marked for deletion
            if (!isMarkedForDeletion) {
              if (!hasComponents && !obsData.value.trim()) {
                return null;
              }

              if (hasComponents && !hasComponentValues) {
                return null;
              }
            }

            const value: QuestionnaireSubmitResultValue = {
              value: obsData.value,
            };

            if (obsData.unit && observationDefinition?.permitted_unit) {
              value.unit = {
                code: obsData.unit,
                system: observationDefinition.permitted_unit.system,
                display:
                  observationDefinition.permitted_unit.display || obsData.unit,
              };
            }

            // Create observation components if they exist and have values
            const components: ObservationComponent[] = [];

            if (hasComponents && observationDefinition) {
              observationDefinition.component?.forEach(
                (componentDef: ObservationDefinitionComponent) => {
                  const componentCode = componentDef.code.code;
                  const componentData = obsData.components[componentCode];

                  if (componentData && componentData.value.trim()) {
                    const componentValue: QuestionnaireSubmitResultValue = {
                      value: componentData.value,
                    };

                    if (componentData.unit && componentDef.permitted_unit) {
                      componentValue.unit = {
                        code: componentData.unit,
                        system: componentDef.permitted_unit.system,
                        display:
                          componentDef.permitted_unit.display ||
                          componentData.unit,
                      };
                    }

                    components.push({
                      code: componentDef.code,
                      value: componentValue,
                    });
                  }
                },
              );
            }

            return {
              ...(obsData.id
                ? { observation_id: obsData.id }
                : { observation_definition: observationDefinition?.slug }),
              observation: {
                status:
                  obsData.status === ObservationStatus.ENTERED_IN_ERROR
                    ? ObservationStatus.ENTERED_IN_ERROR
                    : ObservationStatus.FINAL,
                value_type:
                  observationDefinition?.permitted_data_type || "decimal",
                effective_datetime: new Date().toISOString(),
                value,
                component: components.length > 0 ? components : undefined,
              },
            };
          }),
        )
        .filter((obs): obs is ObservationUpsertRequest => obs !== null);

      const requests: BatchRequestObject[] = [];

      // Upsert observations only when there are results to save
      if (formattedObservations.length > 0) {
        requests.push({
          api: observationApi.upsertObservations,
          referenceId: "upsert-observations",
          pathParams: {
            patient_external_id: patientId,
            external_id: report.id,
          },
          body: {
            observations: formattedObservations,
          },
        });
      }

      requests.push({
        api: diagnosticReportApi.updateDiagnosticReport,
        referenceId: "update-report",
        pathParams: {
          patient_external_id: patientId,
          external_id: report.id,
        },
        body: {
          id: report.id,
          status: report.status,
          category: report.category,
          code: report.code,
          note: report.note,
          conclusion,
        },
      });

      saveReport(requests);
    } catch (_error) {
      toast.error(t("error_validating_form"));
    }
  }

  function handleDeleteObservation(definitionId: string, index: number) {
    const observationsList = observations[definitionId];
    if (!observationsList || !observationsList[index]) return;

    const observation = observationsList[index];
    setObservations((prev) => {
        isExpanded && "bg-gray-100",
      )}
    >
      <Collapsible open={isExpanded} onOpenChange={setIsExpanded}>
        <CardHeader className="px-2 py-4">
          <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-3 sm:gap-2 rounded-md">
            <div className="flex items-center gap-2 min-w-0 w-full sm:w-auto">
              <CardTitle className="min-w-0">
                <CollapsibleTrigger asChild>
                  <button
                    type="button"
                    className="flex items-center gap-2 min-w-0 text-left"
                    onKeyDown={(event) => {
                      if (event.key === "Enter" || event.key === " ") {
                        event.stopPropagation();
                      }
                    }}
                  >
                    <NotepadText className="size-6 shrink-0 text-gray-950 stroke-[1.5px]" />
                    <div className="flex flex-col min-w-0">
                      <span className="text-base text-gray-950 font-medium truncate">
                        {isMultipleDiagnosticReport
                          ? report.code?.display
                          : report.service_request?.title}
                      </span>
                      <span className="text-sm text-gray-500 truncate">
                        {t("last_updated")}:{" "}
                        {format(report.modified_date, "hh:mm a, MMM dd, yyyy")}
                      </span>
                    </div>
                  </button>
                </CollapsibleTrigger>
              </CardTitle>
            </div>
            <div className="flex items-center justify-between sm:justify-end gap-3 sm:gap-5 w-full sm:w-auto">
              {fullReport && (
                <div className="flex items-center gap-2 min-w-0">
                  <Avatar
                    name={formatName(fullReport.created_by, true)}
                    className="size-5 shrink-0"
                    imageUrl={fullReport.created_by.profile_picture_url}
                  />
                  <span className="text-sm text-gray-700 font-medium truncate">
                    {formatName(fullReport.created_by)}
                  </span>
                </div>
              )}

              <div className="flex items-center gap-1 shrink-0">
                <Badge variant={DIAGNOSTIC_REPORT_STATUS_COLORS[report.status]}>
                  {t(report.status)}
                </Badge>
                <CollapsibleTrigger asChild>
                  <Button
                    variant="ghost"
                    size="icon"
                    className="size-10"
                    aria-label={isExpanded ? t("collapse") : t("expand")}
                    onKeyDown={(event) => {
                      if (event.key === "Enter" || event.key === " ") {
                        event.stopPropagation();
                      }
                    }}
                  >
                    {isExpanded ? (
                      <ChevronsDownUp className="size-5" />
                    ) : (
                      <ChevronsUpDown className="size-5" />
                    )}
                  </Button>
                </CollapsibleTrigger>
                {observationDefinitions.length > 0 && (
                  <DropdownMenu>
                    <DropdownMenuTrigger asChild>
                      <Button
                        variant="ghost"
                        size="icon"
                        aria-label={t("view_observation_history")}
                      >
                        <MoreVertical className="size-4" />
                      </Button>
                    </DropdownMenuTrigger>
                    <DropdownMenuContent align="end">
                      <ObservationHistorySheet
                        patientId={patientId}
                        diagnosticReportId={report.id}
                      >
                        <DropdownMenuItem
                          onSelect={(e) => e.preventDefault()}
                          onClick={(e) => {
                            e.stopPropagation();
                          }}
                        >
                          {t("view_observation_history")}
                        </DropdownMenuItem>
                      </ObservationHistorySheet>
                    </DropdownMenuContent>
                  </DropdownMenu>
                )}
              </div>
            </div>
          </div>
        </CardHeader>

        <CollapsibleContent>
          <CardContent className="px-2">
            <PLUGIN_Component
              __name="ServiceRequestAction"
              serviceRequestId={serviceRequestId}
            />
            <div className="space-y-6">
              {report.status !== DiagnosticReportStatus.final && (
                <PLUGIN_Component
                  __name="DiagnosticReportOverride"
                  observationDefinitions={observationDefinitions}
                  handleComponentValueChange={handleComponentValueChange}
                  handleValueChange={handleValueChange}
                  handleUnitChange={handleUnitChange}
                  disabled={isReadOnly}
                />
              )}
              {report.status !== DiagnosticReportStatus.final &&
                observationDefinitions.map((definition) => {
                  const observationsList = observations[definition.id] || [
                    {
                      id: "",
                      value: "",
                      unit: definition.permitted_unit?.code || "",
                      interpretation: "",
                      status: ObservationStatus.AMENDED,
                      components: {},
                    },
                  ];

                  return (
                    <Card
                      key={definition.id}
                      className="mb-4 shadow-none rounded-lg border-gray-200 bg-gray-50"
                    >
                      <CardContent className="p-4">
                        <div className="grid gap-4">
                          <div className="flex justify-between items-start">
                            <Label className="text-base font-semibold text-gray-950">
                              {definition.title || definition.code?.display}
                            </Label>
                          </div>

                          {observationsList.map((observationData, index) => {
                            const hasComponents =
                              definition.component &&
                              definition.component.length > 0;
                            const isErrored =
                              observationData.status ===
                              ObservationStatus.ENTERED_IN_ERROR;
                            return (
                              <div
                                key={index}
                                className={cn(
                                  "space-y-1 bg-gray-200/50 p-4 rounded-lg",
                                  isErrored && "bg-gray-100",
                                )}
                              >
                                <div className="flex justify-between items-center">
                                  <Label className="text-sm font-semibold text-gray-950">
                                    {t("observation") + " " + (index + 1)}
                                  </Label>
                                  {isErrored ? (
                                    <span className="text-sm text-red-500">
                                      {t("marked_for_deletion")}
                                    </span>
                                  ) : (
                                    !isReadOnly && (
                                      <Button
                                        type="button"
                                        variant="ghost"
                                        size="sm"
                                        className="text-destructive hover:text-destructive hover:bg-destructive/10 ml-2"
                                        onClick={() =>
                                          handleDeleteObservation(
                                            definition.id,
                                            index,
                                          )
                                        }
                                        disabled={
                                          isErrored ||
                                          (index === 0 && !observationData.id)
                                        }
                                      >
                                        <Trash2 className="size-4" />
                                      </Button>
                                    )
                                  )}
                                </div>

                                {/* For blood pressure and similar observations with components, we may or may not need to show the main value field */}
                                {!hasComponents && (
                                  <div className="flex flex-col sm:flex-row space-y-4 sm:space-y-0 sm:space-x-4 items-stretch sm:items-center">
                                    {definition.permitted_unit && (
                                      <div className="w-full sm:w-32">
                                        <Label className="text-sm font-medium mb-1 block text-gray-700">
                                          {t("unit")}
                                        </Label>
                                        <Select
                                          value={observationData.unit}
                                          onValueChange={(unit) =>
                                            handleUnitChange(
                                              definition.id,
                                              index,
                                              unit,
                                            )
                                          }
                                          disabled={isErrored || isReadOnly}
                                        >
                                          <SelectTrigger className="w-full">
                                            <SelectValue
                                              placeholder={t("unit")}
                                            />
                                          </SelectTrigger>
                                          <SelectContent>
                                            <SelectItem
                                              value={
                                                definition.permitted_unit.code
                                              }
                                            >
                                              {definition.permitted_unit.code ||
                                                definition.permitted_unit
                                                  .display}
                                            </SelectItem>
                                          </SelectContent>
                                        </Select>
                                      </div>
                                    )}

                                    <div className="flex-1">
                                      <Label className="text-sm font-medium mb-1 block text-gray-700">
                                        {t("result")}
                                      </Label>
                                      <Input
                                        value={observationData.value}
                                        onChange={(e) =>
                                          handleValueChange(
                                            definition.id,
                                            index,
                                            e.target.value,
                                            observationData.unit,
                                          )
                                        }
                                        placeholder={t("result_value")}
                                        type={
                                          definition.permitted_data_type ===
                                            "decimal" ||
                                          definition.permitted_data_type ===
                                            "integer"
                                            ? "number"
                                            : "text"
                                        }
                                        disabled={isErrored || isReadOnly}
                                      />
                                    </div>
                                  </div>
                                )}

                                {/* Render component inputs for multi-component observations */}
                                {hasComponents &&
                                  renderComponentInputs(
                                    definition,
                                    observationData,
                                    index,
                                  )}
                              </div>
                            );
                          })}

                          {/* Add button for multiple observations */}
                          <Button
                            type="button"
                            variant="outline"
                            size="sm"
                            onClick={() => {
                              setObservations((prev) => {
                                const currentList = prev[definition.id] || [];
                                return {
                                  ...prev,
                                  [definition.id]: [
                                    ...currentList,
                                    {
                                      id: "",
                                      value: "",
                                      unit:
                                        definition.permitted_unit?.code || "",
                                      status: ObservationStatus.AMENDED,
                                      components: {},
                                    },
                                  ],
                                };
                              });
                            }}
                            disabled={isReadOnly}
                          >
                            <PlusCircle className="size-4 mr-2" />
                            {t("add_another_result")}
                          </Button>
                        </div>
                      </CardContent>
                    </Card>
                  );
                })}

              <div className="space-y-4">
                {report.status !== DiagnosticReportStatus.final && (
                  <Card className="mb-4 shadow-none rounded-lg border-gray-200 bg-gray-50">
                    <CardContent className="p-4 space-y-2">
                      <Label
                        htmlFor={`conclusion-${report.id}`}
                        className="text-base font-semibold text-gray-950"
                      >
                        {t("conclusion")}
                      </Label>
                      <textarea
                        id={`conclusion-${report.id}`}
                        className="w-full field-sizing-content focus:outline-none focus:ring-1 focus:ring-primary-500 focus:border-primary-500 rounded-lg border border-gray-300 p-2"
                        placeholder={t("enter_conclusion")}
                        value={conclusion}
                        onChange={(e) => setConclusion(e.target.value)}
                        rows={3}
                        disabled={isReadOnly}
                      />
                    </CardContent>
                  </Card>
                )}

                <div className="space-y-4">
                  {fullReport?.status ===
                    DiagnosticReportStatus.preliminary && (
                    <div className="flex justify-end space-x-4">
                      <Button
                        variant="primary"
                        onClick={handleSubmit}
                        disabled={isReadOnly}
                      >
                        <Save className="size-4 mr-2" />
                        {t("save_results")}
                      </Button>
                    </div>
                  )}
                  {files?.results && files.results.length > 0 && (
                    <div className="mt-3">
                      <div className="text-lg font-medium">
                        {t("uploaded_files")}
                      </div>
                      <FileListTable
                        files={files.results}
                        type="diagnostic_report"
                        associatingId={report.id}
                        canEdit={!isReadOnly}
                        showHeader={false}
                      />
                    </div>
                  )}

                  {fullReport?.status ===
                    DiagnosticReportStatus.preliminary && (
                    <div className="space-y-5">
                      <DottedDivider className=" text-gray-500" />
                      <div className="rounded-lg border border-gray-200 bg-gray-50 px-6 py-5 shadow-sm mt-2">
                        <div className="flex flex-col items-center text-center">
                          <h3 className="text-base font-semibold text-gray-950">
                            {t("attach_result_files")}
                          </h3>
                          <p className="mt-1.5 text-sm text-gray-600">
                            {t("add_supporting_photos_or_documents", {
                              formats:
                                BACKEND_ALLOWED_EXTENSIONS.slice(0, 5)
                                  .join(", ")
                                  .toUpperCase() + `, ${t("etc")}`,
                            })}
                          </p>
                          <div className="mt-4 flex flex-col sm:flex-row gap-3 w-full sm:items-center sm:justify-center">
                            <Button
                              variant="outline"
                              className=" border-gray-300 bg-white font-semibold text-gray-950 shadow-sm hover:bg-white"
                              disabled={isReadOnly}
                              onClick={() => fileUpload.handleCameraCapture()}
                            >
                              <Camera className="size-4" />
                              {t("take_photo")}
                            </Button>
                            <Button
                              asChild
                              variant="outline"
                              className={cn(
                                "border-gray-300 bg-white font-semibold text-gray-950 shadow-sm hover:bg-white",
                                isReadOnly
                                  ? "pointer-events-none opacity-50"
                                  : "cursor-pointer",
                              )}
                            >
                              <Label htmlFor={isReadOnly ? undefined : inputId}>
                                <Upload className="size-4" />
                                {t("upload_files")}
                              </Label>
                            </Button>
                            <fileUpload.Input
                              className="hidden"
                              disabled={isReadOnly}
                            />
                          </div>

                          {fileUpload.files.length > 0 && (
                            <div className="mt-5 w-full max-w-md space-y-2">
                              <div
                                className="truncate text-sm text-gray-600"
                                title={fileUpload.files
                                  .map((file) => file.name)
                                  .join(", ")}
                              >
                                {fileUpload.files
                                  .map((file) => file.name)
                                  .join(", ")}
                              </div>
                              <Button
                                type="button"
                                variant="outline"
                                className="w-full border-gray-300 bg-white"
                                disabled={isReadOnly}
                                onClick={() => fileUpload.clearFiles()}
                              >
                                {t("clear")}
                              </Button>
                            </div>
                          )}
                        </div>
                      </div>
                    </div>
                  )}
                </div>
              </div>
            </div>
          </CardContent>
        </CollapsibleContent>
      </Collapsible>

      {fileUpload.Dialogues}
      <FileUploadDialog
        open={openUploadDialog}
        onOpenChange={(open) => {
          if (!open) fileUpload.clearFiles();
        }}
        fileUpload={fileUpload}
        associatingId={report?.id || ""}
        type="diagnostic_report"
        instanceId={report?.id || ""}
      />
    </Card>
  );
}

function ReportTypePicker({
  availableReportCodes,
  hasCollectedSpecimens,
  disableEdit,

item.formatted_output:
  onReportSaved,
}: {
  report: DiagnosticReportRead;
  patientId: string;
  serviceRequestId: string;
  observationDefinitions: ObservationDefinitionRead[];
  disableEdit: boolean;
  facilityId: string;
  isMultipleDiagnosticReport: boolean;
  onReportSaved: (report: SavedReportSignal) => void;
}) {
  const { t } = useTranslation();
  const queryClient = useQueryClient();
  const [observationDraft, setObservationDraft] =
    useState<ObservationsByDefinition | null>(null);
  const [isExpanded, setIsExpanded] = useState(true);
  const [conclusionDraft, setConclusion] = useState<string | undefined>();

  const { data: fullReport } = useQuery({
    queryKey: ["diagnosticReport", report.id],
    queryFn: query(diagnosticReportApi.retrieveDiagnosticReport, {
      pathParams: {
        patient_external_id: patientId,
        external_id: report.id,
      },
    }),
    enabled: !!report.id && isExpanded,
  });

  // Query to fetch files for the diagnostic report
  const { data: files } = useQuery({
    queryKey: ["files", "diagnostic_report", report.id],
    queryFn: query.paginated(fileApi.list, {
      queryParams: {
        file_type: "diagnostic_report",
        associating_id: report.id,
      },
    }),
    enabled: !!report.id && isExpanded,
  });

  // Save observations and update the diagnostic report in a single batch request
  const { mutate: saveReport, isPending: isSubmitting } = useBatchRequest({
    onSuccess: async ({ results }) => {
      if (results.some((r) => r.reference_id === "upsert-observations")) {
        toast.success(t("test_results_saved_successfully"));
      } else {
        toast.success(t("diagnostic_report_saved_successfully"));
      }
      await Promise.all([
        queryClient.invalidateQueries({
          queryKey: ["serviceRequest", facilityId, serviceRequestId],
        }),
        queryClient.invalidateQueries({
          queryKey: ["diagnosticReport", report.id],
        }),
      ]);
      setObservationDraft(null);
      setConclusion(undefined);
      setIsExpanded(false);
      onReportSaved({ id: report.id, savedAt: Date.now() });
    },
  });

  // Initialize file upload hook
  const inputId = `file_upload_diagnostic_report_${report.id}`;
  const fileUpload = useFileUpload({
    type: FileType.DIAGNOSTIC_REPORT,
    inputId,
    multiple: true,
    allowedExtensions: BACKEND_ALLOWED_EXTENSIONS,
    allowNameFallback: false,
    onUpload: () => {
      queryClient.invalidateQueries({
        queryKey: ["diagnosticReport", report.id],
      });
    },
    compress: false,
  });

  const openUploadDialog =
    !disableEdit && fileUpload.files.length > 0 && !fileUpload.previewing;
  const observations = observationDraft ?? getReportObservations(fullReport);
  const conclusion = conclusionDraft ?? fullReport?.conclusion ?? "";
  const isReadOnly =
    disableEdit ||
    !fullReport ||
    isSubmitting ||
    fullReport.status === DiagnosticReportStatus.final;

  function setObservations(
    update: (previous: ObservationsByDefinition) => ObservationsByDefinition,
  ) {
    setObservationDraft((previous) =>
      update(previous ?? getReportObservations(fullReport)),
    );
  }

  function handleValueChange(
    definitionId: string,
    index: number,
    value: string,
    unit?: string,
  ) {
    setObservations((prev) => {
      const observationsList = [...(prev[definitionId] || [])];
      if (!observationsList[index]) {
        observationsList[index] = {
          id: "",
          value: "",
          unit: unit || "",
          status: ObservationStatus.AMENDED,
          components: {},
        };
      }
      observationsList[index] = {
        ...observationsList[index],
        value,
      };
      return {
        ...prev,
        [definitionId]: observationsList,
      };
    });
  }

  function handleUnitChange(definitionId: string, index: number, unit: string) {
    setObservations((prev) => {
      const observationsList = [...(prev[definitionId] || [])];
      if (!observationsList[index]) {
        observationsList[index] = {
          id: "",
          value: "",
          unit: "",
          status: ObservationStatus.AMENDED,
          components: {},
        };
      }
      observationsList[index] = {
        ...observationsList[index],
        unit,
      };
      return {
        ...prev,
        [definitionId]: observationsList,
      };
    });
  }

  function handleComponentValueChange(
    definitionId: string,
    index: number,
    componentCode: string,
    value: string,
    unit: string,
  ) {
    setObservations((prev) => {
      const observationsList = [...(prev[definitionId] || [])];
      if (!observationsList[index]) {
        observationsList[index] = {
          id: "",
          value: "",
          unit: "",
          status: ObservationStatus.AMENDED,
          components: {},
        };
      }
      const observation = observationsList[index];
      const components = { ...observation.components };

      components[componentCode] = {
        ...components[componentCode],
        value,
        unit,
      };

      observationsList[index] = {
        ...observation,
        components,
      };

      return {
        ...prev,
        [definitionId]: observationsList,
      };
    });
  }

  function handleComponentUnitChange(
    definitionId: string,
    index: number,
    componentCode: string,
    unit: string,
  ) {
    setObservations((prev) => {
      const observationsList = [...(prev[definitionId] || [])];
      if (!observationsList[index]) {
        observationsList[index] = {
          id: "",
          value: "",
          unit: "",
          status: ObservationStatus.AMENDED,
          components: {},
        };
      }
      const observation = observationsList[index];
      const components = { ...observation.components };

      components[componentCode] = {
        ...(components[componentCode] || { value: "", interpretation: "" }),
        unit,
      };

      observationsList[index] = {
        ...observation,
        components,
      };

      return {
        ...prev,
        [definitionId]: observationsList,
      };
    });
  }

  function handleSubmit() {
    if (isReadOnly) return;
    try {
      // Check if all observations have values
      const hasObservationValue = Object.values(observations).some((obsList) =>
        obsList.some((obs) => {
          // Skip observations marked as deleted
          if (obs.status === ObservationStatus.ENTERED_IN_ERROR) {
            return false;
          }
          const hasMainValue = obs.value.trim() !== "";
          const hasComponentValue = Object.values(obs.components).some(
            (comp) => comp.value.trim() !== "",
          );
          return hasMainValue || hasComponentValue;
        }),
      );

      // Check if any observations are marked for deletion
      const hasDeletions =
        !hasObservationValue &&
        Object.values(observations).some((obsList) =>
          obsList.some(
            (obs) => obs.status === ObservationStatus.ENTERED_IN_ERROR,
          ),
        );

      // If there's a conclusion, we must have results first
      if (
        conclusion.trim() &&
        !hasObservationValue &&
        observationDefinitions.length > 0
      ) {
        toast.error(t("cannot_add_conclusion_without_results"));
        return;
      }

      // Results are mandatory if observation definitions exist, unless an observation is being deleted
      if (
        !hasObservationValue &&
        !hasDeletions &&
        observationDefinitions.length > 0
      ) {
        toast.error(t("please_fill_all_results"));
        return;
      }

      const formattedObservations: ObservationUpsertRequest[] = Object.entries(
        observations,
      )
        .flatMap(([definitionId, obsList]) =>
          obsList.map((obsData): ObservationUpsertRequest | null => {
            const observationDefinition = observationDefinitions.find(
              (def) => def.id === definitionId,
            );

            // If it's a component-based observation (like blood pressure), we should check if components have values
            const hasComponents =
              observationDefinition?.component &&
              observationDefinition.component.length > 0;
            const hasComponentValues =
              hasComponents &&
              Object.values(obsData.components).some(
                (comp) => comp.value.trim() !== "",
              );

            // For observations marked for deletion, always include them if they have an ID
            const isMarkedForDeletion =
              obsData.status === ObservationStatus.ENTERED_IN_ERROR &&
              obsData.id;

            // For regular observations, skip if no value is entered
            // For component-based observations, check component values
            // But always include observations marked for deletion
            if (!isMarkedForDeletion) {
              if (!hasComponents && !obsData.value.trim()) {
                return null;
              }

              if (hasComponents && !hasComponentValues) {
                return null;
              }
            }

            const value: QuestionnaireSubmitResultValue = {
              value: obsData.value,
            };

            if (obsData.unit && observationDefinition?.permitted_unit) {
              value.unit = {
                code: obsData.unit,
                system: observationDefinition.permitted_unit.system,
                display:
                  observationDefinition.permitted_unit.display || obsData.unit,
              };
            }

            // Create observation components if they exist and have values
            const components: ObservationComponent[] = [];

            if (hasComponents && observationDefinition) {
              observationDefinition.component?.forEach(
                (componentDef: ObservationDefinitionComponent) => {
                  const componentCode = componentDef.code.code;
                  const componentData = obsData.components[componentCode];

                  if (componentData && componentData.value.trim()) {
                    const componentValue: QuestionnaireSubmitResultValue = {
                      value: componentData.value,
                    };

                    if (componentData.unit && componentDef.permitted_unit) {
                      componentValue.unit = {
                        code: componentData.unit,
                        system: componentDef.permitted_unit.system,
                        display:
                          componentDef.permitted_unit.display ||
                          componentData.unit,
                      };
                    }

                    components.push({
                      code: componentDef.code,
                      value: componentValue,
                    });
                  }
                },
              );
            }

            return {
              ...(obsData.id
                ? { observation_id: obsData.id }
                : { observation_definition: observationDefinition?.slug }),
              observation: {
                status:
                  obsData.status === ObservationStatus.ENTERED_IN_ERROR
                    ? ObservationStatus.ENTERED_IN_ERROR
                    : ObservationStatus.FINAL,
                value_type:
                  observationDefinition?.permitted_data_type || "decimal",
                effective_datetime: new Date().toISOString(),
                value,
                component: components.length > 0 ? components : undefined,
              },
            };
          }),
        )
        .filter((obs): obs is ObservationUpsertRequest => obs !== null);

      const requests: BatchRequestObject[] = [];

      // Upsert observations only when there are results to save
      if (formattedObservations.length > 0) {
        requests.push({
          api: observationApi.upsertObservations,
          referenceId: "upsert-observations",
          pathParams: {
            patient_external_id: patientId,
            external_id: report.id,
          },
          body: {
            observations: formattedObservations,
          },
        });
      }

      requests.push({
        api: diagnosticReportApi.updateDiagnosticReport,
        referenceId: "update-report",
        pathParams: {
          patient_external_id: patientId,
          external_id: report.id,
        },
        body: {
          id: report.id,
          status: report.status,
          category: report.category,
          code: report.code,
          note: report.note,
          conclusion,
        },
      });

      saveReport(requests);
    } catch (_error) {
      toast.error(t("error_validating_form"));
    }
  }

  function handleDeleteObservation(definitionId: string, index: number) {
    const observationsList = observations[definitionId];
    if (!observationsList || !observationsList[index]) return;

    const observation = observationsList[index];
    setObservations((prev) => {
        isExpanded && "bg-gray-100",
      )}
    >
      <Collapsible open={isExpanded} onOpenChange={setIsExpanded}>
        <CardHeader className="px-2 py-4">
          <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-3 sm:gap-2 rounded-md">
            <div className="flex items-center gap-2 min-w-0 w-full sm:w-auto">
              <CardTitle className="min-w-0">
                <CollapsibleTrigger asChild>
                  <button
                    type="button"
                    className="flex items-center gap-2 min-w-0 text-left"
                    onKeyDown={(event) => {
                      if (event.key === "Enter" || event.key === " ") {
                        event.stopPropagation();
                      }
                    }}
                  >
                    <NotepadText className="size-6 shrink-0 text-gray-950 stroke-[1.5px]" />
                    <div className="flex flex-col min-w-0">
                      <span className="text-base text-gray-950 font-medium truncate">
                        {isMultipleDiagnosticReport
                          ? report.code?.display
                          : report.service_request?.title}
                      </span>
                      <span className="text-sm text-gray-500 truncate">
                        {t("last_updated")}:{" "}
                        {format(report.modified_date, "hh:mm a, MMM dd, yyyy")}
                      </span>
                    </div>
                  </button>
                </CollapsibleTrigger>
              </CardTitle>
            </div>
            <div className="flex items-center justify-between sm:justify-end gap-3 sm:gap-5 w-full sm:w-auto">
              {fullReport && (
                <div className="flex items-center gap-2 min-w-0">
                  <Avatar
                    name={formatName(fullReport.created_by, true)}
                    className="size-5 shrink-0"
                    imageUrl={fullReport.created_by.profile_picture_url}
                  />
                  <span className="text-sm text-gray-700 font-medium truncate">
                    {formatName(fullReport.created_by)}
                  </span>
                </div>
              )}

              <div className="flex items-center gap-1 shrink-0">
                <Badge variant={DIAGNOSTIC_REPORT_STATUS_COLORS[report.status]}>
                  {t(report.status)}
                </Badge>
                <CollapsibleTrigger asChild>
                  <Button
                    variant="ghost"
                    size="icon"
                    className="size-10"
                    aria-label={isExpanded ? t("collapse") : t("expand")}
                    onKeyDown={(event) => {
                      if (event.key === "Enter" || event.key === " ") {
                        event.stopPropagation();
                      }
                    }}
                  >
                    {isExpanded ? (
                      <ChevronsDownUp className="size-5" />
                    ) : (
                      <ChevronsUpDown className="size-5" />
                    )}
                  </Button>
                </CollapsibleTrigger>
                {observationDefinitions.length > 0 && (
                  <DropdownMenu>
                    <DropdownMenuTrigger asChild>
                      <Button
                        variant="ghost"
                        size="icon"
                        aria-label={t("view_observation_history")}
                      >
                        <MoreVertical className="size-4" />
                      </Button>
                    </DropdownMenuTrigger>
                    <DropdownMenuContent align="end">
                      <ObservationHistorySheet
                        patientId={patientId}
                        diagnosticReportId={report.id}
                      >
                        <DropdownMenuItem
                          onSelect={(e) => e.preventDefault()}
                          onClick={(e) => {
                            e.stopPropagation();
                          }}
                        >
                          {t("view_observation_history")}
                        </DropdownMenuItem>
                      </ObservationHistorySheet>
                    </DropdownMenuContent>
                  </DropdownMenu>
                )}
              </div>
            </div>
          </div>
        </CardHeader>

        <CollapsibleContent>
          <CardContent className="px-2">
            <PLUGIN_Component
              __name="ServiceRequestAction"
              serviceRequestId={serviceRequestId}
            />
            <div className="space-y-6">
              {report.status !== DiagnosticReportStatus.final && (
                <PLUGIN_Component
                  __name="DiagnosticReportOverride"
                  observationDefinitions={observationDefinitions}
                  handleComponentValueChange={handleComponentValueChange}
                  handleValueChange={handleValueChange}
                  handleUnitChange={handleUnitChange}
                  disabled={isReadOnly}
                />
              )}
              {report.status !== DiagnosticReportStatus.final &&
                observationDefinitions.map((definition) => {
                  const observationsList = observations[definition.id] || [
                    {
                      id: "",
                      value: "",
                      unit: definition.permitted_unit?.code || "",
                      interpretation: "",
                      status: ObservationStatus.AMENDED,
                      components: {},
                    },
                  ];

                  return (
                    <Card
                      key={definition.id}
                      className="mb-4 shadow-none rounded-lg border-gray-200 bg-gray-50"
                    >
                      <CardContent className="p-4">
                        <div className="grid gap-4">
                          <div className="flex justify-between items-start">
                            <Label className="text-base font-semibold text-gray-950">
                              {definition.title || definition.code?.display}
                            </Label>
                          </div>

                          {observationsList.map((observationData, index) => {
                            const hasComponents =
                              definition.component &&
                              definition.component.length > 0;
                            const isErrored =
                              observationData.status ===
                              ObservationStatus.ENTERED_IN_ERROR;
                            return (
                              <div
                                key={index}
                                className={cn(
                                  "space-y-1 bg-gray-200/50 p-4 rounded-lg",
                                  isErrored && "bg-gray-100",
                                )}
                              >
                                <div className="flex justify-between items-center">
                                  <Label className="text-sm font-semibold text-gray-950">
                                    {t("observation") + " " + (index + 1)}
                                  </Label>
                                  {isErrored ? (
                                    <span className="text-sm text-red-500">
                                      {t("marked_for_deletion")}
                                    </span>
                                  ) : (
                                    !isReadOnly && (
                                      <Button
                                        type="button"
                                        variant="ghost"
                                        size="sm"
                                        className="text-destructive hover:text-destructive hover:bg-destructive/10 ml-2"
                                        onClick={() =>
                                          handleDeleteObservation(
                                            definition.id,
                                            index,
                                          )
                                        }
                                        disabled={
                                          isErrored ||
                                          (index === 0 && !observationData.id)
                                        }
                                      >
                                        <Trash2 className="size-4" />
                                      </Button>
                                    )
                                  )}
                                </div>

                                {/* For blood pressure and similar observations with components, we may or may not need to show the main value field */}
                                {!hasComponents && (
                                  <div className="flex flex-col sm:flex-row space-y-4 sm:space-y-0 sm:space-x-4 items-stretch sm:items-center">
                                    {definition.permitted_unit && (
                                      <div className="w-full sm:w-32">
                                        <Label className="text-sm font-medium mb-1 block text-gray-700">
                                          {t("unit")}
                                        </Label>
                                        <Select
                                          value={observationData.unit}
                                          onValueChange={(unit) =>
                                            handleUnitChange(
                                              definition.id,
                                              index,
                                              unit,
                                            )
                                          }
                                          disabled={isErrored || isReadOnly}
                                        >
                                          <SelectTrigger className="w-full">
                                            <SelectValue
                                              placeholder={t("unit")}
                                            />
                                          </SelectTrigger>
                                          <SelectContent>
                                            <SelectItem
                                              value={
                                                definition.permitted_unit.code
                                              }
                                            >
                                              {definition.permitted_unit.code ||
                                                definition.permitted_unit
                                                  .display}
                                            </SelectItem>
                                          </SelectContent>
                                        </Select>
                                      </div>
                                    )}

                                    <div className="flex-1">
                                      <Label className="text-sm font-medium mb-1 block text-gray-700">
                                        {t("result")}
                                      </Label>
                                      <Input
                                        value={observationData.value}
                                        onChange={(e) =>
                                          handleValueChange(
                                            definition.id,
                                            index,
                                            e.target.value,
                                            observationData.unit,
                                          )
                                        }
                                        placeholder={t("result_value")}
                                        type={
                                          definition.permitted_data_type ===
                                            "decimal" ||
                                          definition.permitted_data_type ===
                                            "integer"
                                            ? "number"
                                            : "text"
                                        }
                                        disabled={isErrored || isReadOnly}
                                      />
                                    </div>
                                  </div>
                                )}

                                {/* Render component inputs for multi-component observations */}
                                {hasComponents &&
                                  renderComponentInputs(
                                    definition,
                                    observationData,
                                    index,
                                  )}
                              </div>
                            );
                          })}

                          {/* Add button for multiple observations */}
                          <Button
                            type="button"
                            variant="outline"
                            size="sm"
                            onClick={() => {
                              setObservations((prev) => {
                                const currentList = prev[definition.id] || [];
                                return {
                                  ...prev,
                                  [definition.id]: [
                                    ...currentList,
                                    {
                                      id: "",
                                      value: "",
                                      unit:
                                        definition.permitted_unit?.code || "",
                                      status: ObservationStatus.AMENDED,
                                      components: {},
                                    },
                                  ],
                                };
                              });
                            }}
                            disabled={isReadOnly}
                          >
                            <PlusCircle className="size-4 mr-2" />
                            {t("add_another_result")}
                          </Button>
                        </div>
                      </CardContent>
                    </Card>
                  );
                })}

              <div className="space-y-4">
                {report.status !== DiagnosticReportStatus.final && (
                  <Card className="mb-4 shadow-none rounded-lg border-gray-200 bg-gray-50">
                    <CardContent className="p-4 space-y-2">
                      <Label
                        htmlFor={`conclusion-${report.id}`}
                        className="text-base font-semibold text-gray-950"
                      >
                        {t("conclusion")}
                      </Label>
                      <textarea
