import { EncounterQuestion } from "./EncounterQuestion";
import { FilesQuestion } from "./FileQuestion";
import { MedicationRequestQuestion } from "./MedicationRequestQuestion";
import { MedicationStatementQuestion } from "./MedicationStatementQuestion";
import { NumberQuestion } from "./NumberQuestion";
import { QuantityQuestion } from "./QuantityQuestion";
import { ServiceRequestQuestion } from "./ServiceRequestQuestion";
import { SymptomQuestion } from "./SymptomQuestion";
import { TextQuestion } from "./TextQuestion";
import { TimeQuestion } from "./TimeQuestion";

// Wrapper component for inputs with integrated notes icon
function InputWithNotes({
  children,
  questionnaireResponse,
  onUpdateNote,
  disabled,
}: {
  children: React.ReactNode;
  questionnaireResponse: QuestionnaireResponse;
  onUpdateNote: (note: string) => void;
  disabled?: boolean;
}) {
  const { t } = useTranslation();
  const [notesOpen, setNotesOpen] = useState(false);
  const notes = questionnaireResponse.note || "";
  const hasNotes = notes.length > 0;

  return (
    <div className="flex items-stretch">
      <div className="flex-1 min-w-0 [&_input]:border-r-0 [&_input]:rounded-r-none [&_input]:shadow-none [&_input]:focus-visible:ring-0 [&_textarea]:border-r-0 [&_textarea]:rounded-r-none [&_textarea]:shadow-none [&_textarea]:focus-visible:ring-0 [&_button[role=combobox]]:border-r-0 [&_button[role=combobox]]:rounded-r-none [&_button[role=combobox]]:shadow-none">
        {children}
      </div>
      <Popover open={notesOpen} onOpenChange={setNotesOpen}>
        <PopoverTrigger asChild>
          <button
            type="button"
            disabled={disabled}
            className={cn(
              "flex items-center justify-center w-10 border border-gray-300 rounded-r-md bg-gray-100/20",
              hasNotes && "bg-orange-50",
            )}
          >
            <CareIcon
              icon={hasNotes ? "l-notes" : "l-file-medical-alt"}
              className={cn(
                "size-4",
                hasNotes ? "text-orange-600" : "text-gray-500",
              )}
            />
          </button>
        </PopoverTrigger>
        <PopoverContent
          className="w-72 bg-orange-50 border border-orange-200 shadow-lg p-2"
          align="end"
        >
          <Textarea
            value={notes}
            onChange={(e) => onUpdateNote(e.target.value)}
            className="bg-white border-orange-200 focus-visible:border-orange-300 focus-visible:ring-orange-300"
            placeholder={t("add_notes")}
            disabled={disabled}
          />
        </PopoverContent>
      </Popover>
    </div>
  );
}

// Notes button for repeating questions (standalone icon button)
function RepeatingNotesButton({
  questionnaireResponse,
  onUpdateNote,
  disabled,
}: {
  questionnaireResponse: QuestionnaireResponse;
  onUpdateNote: (note: string) => void;
  disabled?: boolean;
}) {
  const { t } = useTranslation();
  const [notesOpen, setNotesOpen] = useState(false);
  const notes = questionnaireResponse.note || "";
  const hasNotes = notes.length > 0;

  return (
    <Popover open={notesOpen} onOpenChange={setNotesOpen}>
                  observationDefinitions={reportDefinitions}
                  handleComponentValueChange={handleComponentValueChange}
                  handleValueChange={handleValueChange}
                  handleUnitChange={handleUnitChange}
                  disabled={isReadOnly}
                />
              )}
              {report.status !== DiagnosticReportStatus.final && (
                <section
                  aria-labelledby={`observations-${report.id}`}
                  className="rounded-lg border border-gray-200 bg-white px-4"
                >
                  <div className="flex flex-wrap items-center justify-between gap-2 border-b border-gray-200 py-3">
                    <h3
                      id={`observations-${report.id}`}
                      className="text-base font-semibold text-gray-950"
                    >
                      {t("observations")}
                    </h3>
                    <DiagnosticReportObservationPicker
                      facilityId={facilityId}
                      selectedIds={reportDefinitions.map(
                        (definition) => definition.id,
                      )}
                      disabled={isReadOnly}
                      onSelect={(definition) => {
                        setAddedDefinitions((previous) => [
                          ...previous,
                          definition,
                        ]);
                        setObservations((previous) => ({
                          ...previous,
                          [definition.id]: [
                            {
                              id: "",
                              value: "",
                              unit: definition.permitted_unit?.code || "",
                              status: ObservationStatus.AMENDED,
                              components: {},
                            },
                          ],
                        }));
                      }}
                    />
                  </div>
                  <div className="divide-y divide-gray-200">
                    {reportDefinitions.map((definition) => {
                      const observationsList = observations[definition.id] || [
                        {
                          id: "",
                          value: "",
                          unit: definition.permitted_unit?.code || "",
                          interpretation: "",
                          status: ObservationStatus.AMENDED,
                          components: {},
                        },
                      ];
                      const title = definition.title || definition.code.display;
                      const titleId = `observation-title-${report.id}-${definition.id}`;
                      const hasComponents = !!definition.component?.length;

                      return (
                        <Card
                          key={definition.id}
                          role="group"
                          aria-labelledby={titleId}
                          className="rounded-none border-0 bg-transparent shadow-none"
                        >
                          <CardContent className="grid gap-3 px-0 py-4 sm:grid-cols-[minmax(0,1fr)_minmax(0,2fr)] sm:gap-6">
                            <div
                              id={titleId}
                              className="pt-2 text-sm font-medium text-gray-950 wrap-break-word"
                            >
                              {title}
                            </div>
                            <div className="min-w-0 space-y-2">
                              <div className="space-y-3">
                                {observationsList.map(
                                  (observationData, index) => {
                                    const isErrored =
                                      observationData.status ===
                                      ObservationStatus.ENTERED_IN_ERROR;
                                    const inputId = `observation-${report.id}-${definition.id}-${index}`;

                                    return (
                                      <div
                                        key={index}
                                        role="group"
                                        aria-label={`${t("result")} ${index + 1}`}
                                        className="space-y-1.5"
                                      >
                                        {isErrored && (
                                          <p className="text-sm text-red-600">
                                            {t("marked_for_deletion")}
                                          </p>
                                        )}
                                        <div className="flex items-start gap-2">
                                          {observationsList.length > 1 && (
                                            <span
                                              aria-hidden="true"
                                              className={cn(
                                                "w-4 shrink-0 pt-2.5 text-xs text-gray-500 tabular-nums",
                                                hasComponents && "pt-8",
                                              )}
                                            >
                                              {index + 1}.
                                            </span>
                                          )}
                                          {hasComponents ? (
                                            renderComponentInputs(
                                              definition,
                                              observationData,
                                              index,
                                            )
                                          ) : (
                                            <DiagnosticReportObservationInput
                                              id={inputId}
                                              label={title}
                                              value={observationData.value}
                                              unit={observationData.unit}
                                              permittedUnit={
                                                definition.permitted_unit
                                              }
                                              dataType={
                                                definition.permitted_data_type
                                              }
                                              placeholder={t("result_value")}
                                              disabled={isErrored || isReadOnly}
                                              onValueChange={(value) =>
                                                handleValueChange(
                                                  definition.id,
                                                  index,
                                                  value,
                                                  observationData.unit,
                                                )
                                              }
                                              onUnitChange={(unit) =>
                                                handleUnitChange(
                                                  definition.id,
                                                  index,
                                                  unit,
                                                )
                                              }
                                            />
                                          )}
                                          {!isErrored && !isReadOnly && (
                                            <Button
                                              type="button"
                                              variant="ghost"
                                              size="icon"
                                              className={cn(
                                                "size-10 shrink-0 text-gray-500 hover:text-destructive hover:bg-destructive/10",
                                                hasComponents && "mt-6",
                                              )}
                                              aria-label={t(
                                                "remove_observation",
                                              )}
                                              onClick={() =>
                                                handleDeleteObservation(
                                                  definition.id,
                                                  index,
                                                )
                                              }
                                              disabled={
                                                index === 0 &&
                                                !observationData.id &&
                                                observationDefinitions.some(
                                                  (required) =>
                                                    required.id ===
                                                    definition.id,
                                                )
                                              }
                                            >
                                              <Trash2 className="size-4" />
                                            </Button>
                                          )}
                                        </div>
                                      </div>
                                    );
                                  },
                                )}
                              </div>
                              <Button
                                type="button"
                                variant="ghost"
                                size="sm"
                                className="-ml-2 h-8 text-xs text-gray-600"
                                onClick={() => {
                                  setObservations((prev) => {
                                    const currentList =
                                      prev[definition.id] ?? observationsList;
                                    return {
                                      ...prev,
                                      [definition.id]: [
                                        ...currentList,
                                        {
                                          id: "",
                                          value: "",
                                          unit:
                                            definition.permitted_unit?.code ||
                                            "",
                                          status: ObservationStatus.AMENDED,
                                          components: {},
                                        },
                                      ],
                                    };
                                  });
                                }}
                                disabled={isReadOnly}
                              >
                                <Plus className="size-3.5" />
                                {t("add_another_result")}
                              </Button>
                            </div>
                          </CardContent>
                        </Card>
                      );
                    })}
                  </div>
                </section>
              )}

              <div className="space-y-4">
                {report.status !== DiagnosticReportStatus.final && (
                  <Card className="mb-4 shadow-none rounded-lg border-gray-200 bg-white">
                    <CardContent className="p-4 space-y-2">
                      <Label
                        htmlFor={`conclusion-${report.id}`}
                        className="text-base font-semibold text-gray-950"
                      >
                        {t("conclusion")}
                      </Label>
                      <textarea
                        id={`conclusion-${report.id}`}
                        className="w-full field-sizing-content focus:outline-none focus:ring-1 focus:ring-primary-500 focus:border-primary-500 rounded-lg border border-gray-300 p-2"
                        placeholder={t("enter_conclusion")}
                        value={conclusion}
                        onChange={(e) => setConclusion(e.target.value)}
                        rows={3}
                        disabled={isReadOnly}
                      />
                    </CardContent>
                  </Card>
                )}

                <div className="space-y-4">
                  {fullReport?.status ===
                    DiagnosticReportStatus.preliminary && (
                    <div className="flex justify-end space-x-4">
                      <Button
                        variant="primary"
                        onClick={handleSubmit}
                        disabled={isReadOnly}
                      >
                        <Save className="size-4 mr-2" />
                        {t("save_results")}
                      </Button>
                    </div>
                  )}
                  {files?.results && files.results.length > 0 && (
